#!/usr/bin/env node
// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: 2026 avtc <tarasenkov@gmail.com>
//
// The host-untouched gate: the pi source tree (src/, index.ts) is
// byte-identical to the pre-port baseline, and the pi test tree (tests/)
// differs only by the recorded allowlist (new test-infrastructure files the
// vendored core needs, plus one cosmetic formatter wrap). Any other change
// to pi-owned files fails the gate — the port must live in claude/ and the
// sanctioned root surfaces (scripts, devDeps, tool configs, vitest
// registrations) alone.
//
// Usage: node scripts/h5-host-untouched.cjs [--repo <dir>] [--base <sha>]
// Exit 0 = clean; 1 = violations (listed); 2 = usage/environment errors.

"use strict";

const { execFileSync } = require("node:child_process");
const path = require("node:path");

const argv = process.argv.slice(2);
const flag = (name, def) => {
  const i = argv.indexOf(`--${name}`);
  return i === -1 ? def : argv[i + 1];
};

const repo = flag("repo", path.join(__dirname, ".."));
let base = flag("base", null);

// The pre-port baseline: the parent of the first port commit (the commit
// that added claude/.claude-plugin/plugin.json). Overridable for tests.
if (base === null) {
  const firstPort = execFileSync(
    "git",
    ["log", "--oneline", "--diff-filter=A", "--", "claude/.claude-plugin/plugin.json"],
    {
      cwd: repo,
      encoding: "utf8",
    },
  )
    .trim()
    .split("\n")
    .pop();
  if (firstPort === undefined || firstPort === "") {
    process.stderr.write("h5-host-untouched: cannot locate the first port commit\n");
    process.exit(2);
  }
  base = `${firstPort.split(" ")[0]}^`;
}

