function diffNames(from, to, paths) {
  const out = execFileSync("git", ["diff", "--name-status", from, to, "--", ...paths], {
    cwd: repo,
    encoding: "utf8",
  });
  return out
    .trim()
    .split("\n")
    .filter((l) => l !== "")
    .map((l) => {
      const [status, name] = l.split("\t");
      return { status, name };
    });
}

/** The body lines of a file's diff (+/- only, headers stripped). */
function diffBody(from, to, name) {
  const out = execFileSync("git", ["diff", from, to, "--", name], { cwd: repo, encoding: "utf8" });
  return out
    .split("\n")
    .filter((l) => (l.startsWith("+") || l.startsWith("-")) && !l.startsWith("+++") && !l.startsWith("---"))
    .map((l) => l.replace(/\r$/, ""));
}

const violations = [];

for (const { status, name } of diffNames(base, "HEAD", ["src/", "index.ts"])) {
  if (status === "A" && SRC_ADDED.has(name)) continue; // recorded new file
  if (status === "M" && SRC_MODIFIED_PINNED.has(name)) {
    const body = diffBody(base, "HEAD", name);
    const pinned = SRC_MODIFIED_PINNED.get(name);
    if (body.length === pinned.length && body.every((l, i) => l === pinned[i])) continue;
    violations.push(`src-surface: ${status} ${name} (diff grew beyond the recorded hunk set)`);
    continue;
  }
  violations.push(`src-surface: ${status} ${name}`);
}

for (const { status, name } of diffNames(base, "HEAD", ["tests/"])) {
  if (status === "A" && TESTS_ADDED.has(name)) continue; // recorded new file
  if (status === "M" && TESTS_MODIFIED_PINNED.has(name)) {
    const body = diffBody(base, "HEAD", name);
    const pinned = TESTS_MODIFIED_PINNED.get(name);
    if (body.length === pinned.length && body.every((l, i) => l === pinned[i])) continue;
    violations.push(`tests-surface: ${status} ${name} (diff grew beyond the recorded hunk set)`);
    continue;
  }
  violations.push(`tests-surface: ${status} ${name}`);
}

if (violations.length > 0) {
  process.stderr.write(`h5-host-untouched: ${violations.length} violation(s)\n`);
  for (const v of violations) process.stderr.write(`  ${v}\n`);
  process.exit(1);
}

process.stdout.write(
  "h5-host-untouched: clean (src/ + index.ts within the recorded, content-pinned hunks; tests/ likewise)\n",
);
process.exit(0);
